<?php
require_once __DIR__.'/support/customers-design.php';
$html=App\Core\View::partial('admin/customers/index',customersDesignData('empty'));check(!str_contains($html,'M07')&&!str_contains($html,'ficticios'),'Customer copy is written for end users');check(str_contains($html,'Registrar primer cliente'),'Empty directory offers creation');
$html=App\Core\View::partial('admin/customers/index',customersDesignData('filtered'));check(str_contains($html,'No encontramos clientes'),'Filtered empty state explains no matches');
$html=App\Core\View::partial('admin/customers/index',customersDesignData('populated'));foreach(['create','edit','detail','status'] as $action)check(str_contains($html,'data-admin-form-link href="/admin/customers/'.$action),'Customer action uses modal '.$action);check(!str_contains($html,'data-confirm'),'Customer status uses modal instead of native confirmation');
$html=App\Core\View::partial('admin/customers/index',customersDesignData('restricted'));foreach(['create','edit','status'] as $action)check(!str_contains($html,'/admin/customers/'.$action),'Customer action is hidden without permission '.$action);
$html=App\Core\View::partial('admin/customers/form',customersDesignData('error'));check(str_contains($html,'Nombre conservado')&&str_contains($html,'Contacto conservado'),'Form preserves submitted values');check(str_contains($html,'role="alert"'),'Form exposes validation error');
foreach(['branch_id','customer_type','code','legal_name','trade_name','tax_identifier','email','phone','alternate_phone','price_list_id','notes','contact_name','contact_role','contact_phone','contact_email','address_type','address_line1','address_line2','city','state_name','postal_code'] as $field)check(str_contains($html,'name="'.$field.'"'),'Customer field preserved '.$field);
$data=customersDesignData('edit');$data['values']=['lock_version'=>'1','legal_name'=>'<script>unsafe</script>'];$html=App\Core\View::partial('admin/customers/form',$data);check(str_contains($html,'name="lock_version" value="1"'),'Validation does not silently refresh concurrency version');check(!str_contains($html,'<script>'),'Customer values remain escaped');
